export async function getThread(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  return commentRepo.listThread(orgId, issueId);
}

/**
 * The issue author, the current assignee, and authors of comments that have
 * not been deleted. Each person appears once, and only while they are an
 * active member of the organization. Reading the thread is enough to call this.
 */
export async function getIssueParticipants(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  const candidates = new Set<UserId>(
    await commentRepo.listCommentAuthorIds(orgId, issueId),
  );
  candidates.add(issue.authorId);
  if (issue.assigneeId !== null) candidates.add(issue.assigneeId);

  const participants: UserId[] = [];
  for (const userId of candidates) {
    const member = await memberRepo.findMember(orgId, userId);
    if (member !== null && member.status === "active") {
      participants.push(userId);
    }
  }
  return participants;
}

