import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { issueParticipantsSchema } from "@/schemas/comment";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;
let issue: Issue;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("participants-north");
  acme = await createTenant("participants-acme");
  issue = await issueService.createIssue(
    north.actors.member,
    issueInput(north.org.id, north.project.id, {
      title: "Participants",
      assigneeId: north.userIds.admin,
    }),
  );
});

afterAll(() => {
  cleanup();
});

describe("issue participants", () => {
  it("validates org and issue ids like the other comment schemas", () => {
    expect(
      issueParticipantsSchema.parse({ orgId: north.org.id, issueId: issue.id }),
    ).toEqual({ orgId: north.org.id, issueId: issue.id });
    expect(
      issueParticipantsSchema.safeParse({ orgId: "nope", issueId: issue.id }).success,
    ).toBe(false);
    expect(
      issueParticipantsSchema.safeParse({ orgId: north.org.id, issueId: "nope" }).success,
    ).toBe(false);
  });

  it("lists distinct live comment authors, including replies", async () => {
    const top = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "from owner",
        parentId: null,
        mentionedUserIds: [],
      },
      north.userIds.owner,
    );
    await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "owner again",
        parentId: null,
        mentionedUserIds: [],
      },
      north.userIds.owner,
    );
    await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "viewer reply",
        parentId: top.id,
        mentionedUserIds: [],
      },
      north.userIds.viewer,
    );
    const deleted = await commentRepo.insertComment(
      {
        orgId: north.org.id,
        issueId: issue.id,
        body: "admin only deleted",
        parentId: null,
        mentionedUserIds: [],
      },
      north.userIds.admin,
    );
    await commentRepo.archiveComment(north.org.id, deleted.id);

    const ids = await commentRepo.listCommentAuthorIds(north.org.id, issue.id);
    expect(new Set(ids)).toEqual(new Set([north.userIds.owner, north.userIds.viewer]));
    expect(ids.filter((id) => id === north.userIds.owner)).toHaveLength(1);
  });

  it("returns author, assignee, and live commenters once, for a viewer", async () => {
    const participants = await commentService.getIssueParticipants(
      north.actors.viewer,
      north.org.id,
      issue.id,
    );
    expect(new Set(participants)).toEqual(
      new Set([
        north.userIds.member,
        north.userIds.admin,
        north.userIds.owner,
        north.userIds.viewer,
      ]),
    );
    expect(participants).toHaveLength(4);
  });

  it("drops someone whose only comments were deleted, unless they are author or assignee", async () => {
    const other = await issueService.createIssue(
      north.actors.owner,
      issueInput(north.org.id, north.project.id, { title: "Deleted only" }),
    );
    const comment = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: other.id,
      body: "will vanish",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(north.actors.admin, {
      orgId: north.org.id,
      commentId: comment.id,
    });

    const participants = await commentService.getIssueParticipants(
      north.actors.viewer,
      north.org.id,
      other.id,
    );
    expect(new Set(participants)).toEqual(new Set([north.userIds.owner]));
  });

  it("leaves out a removed author", async () => {
    const authored = await issueService.createIssue(
      north.actors.admin,
      issueInput(north.org.id, north.project.id, {
        title: "Admin authored",
        assigneeId: north.userIds.viewer,
      }),
    );
    await commentService.createComment(north.actors.admin, {
      orgId: north.org.id,
      issueId: authored.id,
      body: "admin note",
      parentId: null,
      mentionedUserIds: [],
    });
    const adminMember = await memberRepo.findMember(north.org.id, north.userIds.admin);
    expect(adminMember).not.toBeNull();
    await memberRepo.archiveMember(north.org.id, adminMember!.id);

    const participants = await commentService.getIssueParticipants(
      north.actors.owner,
      north.org.id,
      authored.id,
    );
    expect(new Set(participants)).toEqual(new Set([north.userIds.viewer]));
  });

  it("rejects a foreign org, a missing issue, and another tenant's issue id", async () => {
    const acmeIssue = await issueService.createIssue(
      acme.actors.member,
      issueInput(acme.org.id, acme.project.id, { title: "Acme" }),
    );

    await expect(
      commentService.getIssueParticipants(north.actors.owner, acme.org.id, acmeIssue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      commentService.getIssueParticipants(
        north.actors.owner,
        north.org.id,
        acmeIssue.id,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.getIssueParticipants(
        north.actors.owner,
        north.org.id,
        "01HZZZSSSSSSSSSSSSSSSSSSSS" as Issue["id"],
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("denies an actor who cannot read the thread", async () => {
    const outsider = {
      ...north.actors.viewer,
      role: "guest",
    } as unknown as Actor;

    await expect(
      commentService.getIssueParticipants(outsider, north.org.id, issue.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
});

